import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { motion } from 'framer-motion';
import { FiBook, FiUsers, FiAward, FiCheck } from 'react-icons/fi';
import CourseCard from '../components/ui/CourseCard';

const Home = () => {
  const [featuredCourses, setFeaturedCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        const res = await axios.get('/api/courses');
        // Only take first 3 courses for featured section
        setFeaturedCourses(res.data.slice(0, 3));
        setLoading(false);
      } catch (err) {
        console.error('Error fetching courses:', err);
        setError('حدث خطأ أثناء تحميل الدورات');
        setLoading(false);
      }
    };

    fetchCourses();
  }, []);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        delayChildren: 0.3,
        staggerChildren: 0.2
      }
    }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1
    }
  };

  return (
    <div>
      {/* Hero Section */}
      <section className="bg-gradient-to-br from-primary-600 to-primary-900 text-white py-20 px-4">
        <div className="container mx-auto text-center">
          <motion.h1
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="text-4xl md:text-5xl font-bold mb-6"
          >
            منصة التعليم العربية المتكاملة
          </motion.h1>
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="text-xl md:text-2xl mb-8 max-w-3xl mx-auto"
          >
            منصة تعليمية متكاملة توفر دورات عالية الجودة على يد نخبة من أفضل المعلمين
          </motion.p>
          <motion.div
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.5, delay: 0.4 }}
            className="flex flex-col sm:flex-row justify-center gap-4"
          >
            <Link to="/courses" className="bg-white text-primary-700 hover:bg-gray-100 px-8 py-3 rounded-md text-lg font-semibold transition-colors">
              استعرض الدورات
            </Link>
            <Link to="/register/student" className="bg-transparent border-2 border-white hover:bg-white/10 px-8 py-3 rounded-md text-lg font-semibold transition-colors">
              انضم كطالب
            </Link>
          </motion.div>
        </div>
      </section>

      {/* Features Section */}
      <section className="py-16 px-4 bg-gray-50 dark:bg-gray-800">
        <div className="container mx-auto">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-bold mb-4 text-gray-900 dark:text-white">ما يميز منصتنا</h2>
            <p className="text-gray-600 dark:text-gray-300 max-w-2xl mx-auto">
              نقدم لك تجربة تعليمية فريدة من نوعها مع مجموعة من المزايا التي تساعدك على تحقيق أهدافك التعليمية
            </p>
          </div>

          <motion.div
            variants={containerVariants}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.3 }}
            className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8"
          >
            <motion.div variants={itemVariants} className="card text-center">
              <div className="flex justify-center mb-4">
                <div className="rounded-full bg-primary-100 dark:bg-primary-900 p-4">
                  <FiBook className="h-8 w-8 text-primary-600 dark:text-primary-300" />
                </div>
              </div>
              <h3 className="text-xl font-bold mb-2 text-gray-900 dark:text-white">دورات متنوعة</h3>
              <p className="text-gray-600 dark:text-gray-300">
                مجموعة واسعة من الدورات في مختلف المجالات العلمية والثقافية
              </p>
            </motion.div>

            <motion.div variants={itemVariants} className="card text-center">
              <div className="flex justify-center mb-4">
                <div className="rounded-full bg-primary-100 dark:bg-primary-900 p-4">
                  <FiUsers className="h-8 w-8 text-primary-600 dark:text-primary-300" />
                </div>
              </div>
              <h3 className="text-xl font-bold mb-2 text-gray-900 dark:text-white">معلمون متميزون</h3>
              <p className="text-gray-600 dark:text-gray-300">
                نخبة من أفضل المعلمين ذوي الخبرة والكفاءة العالية
              </p>
            </motion.div>

            <motion.div variants={itemVariants} className="card text-center">
              <div className="flex justify-center mb-4">
                <div className="rounded-full bg-primary-100 dark:bg-primary-900 p-4">
                  <FiAward className="h-8 w-8 text-primary-600 dark:text-primary-300" />
                </div>
              </div>
              <h3 className="text-xl font-bold mb-2 text-gray-900 dark:text-white">شهادات معتمدة</h3>
              <p className="text-gray-600 dark:text-gray-300">
                شهادات إتمام معتمدة لكل دورة تكملها بنجاح
              </p>
            </motion.div>

            <motion.div variants={itemVariants} className="card text-center">
              <div className="flex justify-center mb-4">
                <div className="rounded-full bg-primary-100 dark:bg-primary-900 p-4">
                  <FiCheck className="h-8 w-8 text-primary-600 dark:text-primary-300" />
                </div>
              </div>
              <h3 className="text-xl font-bold mb-2 text-gray-900 dark:text-white">تعلم مرن</h3>
              <p className="text-gray-600 dark:text-gray-300">
                تعلم بالسرعة التي تناسبك وفي الوقت المناسب لك
              </p>
            </motion.div>
          </motion.div>
        </div>
      </section>

      {/* Featured Courses Section */}
      <section className="py-16 px-4">
        <div className="container mx-auto">
          <div className="flex justify-between items-center mb-12">
            <h2 className="text-3xl font-bold text-gray-900 dark:text-white">الدورات المميزة</h2>
            <Link to="/courses" className="btn-outline">
              عرض جميع الدورات
            </Link>
          </div>

          {loading ? (
            <div className="flex justify-center">
              <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
            </div>
          ) : error ? (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded">
              {error}
            </div>
          ) : featuredCourses.length === 0 ? (
            <div className="text-center py-8">
              <p className="text-gray-600 dark:text-gray-300 text-lg">لا توجد دورات متاحة حالياً</p>
              <Link to="/register/teacher" className="btn-primary mt-4 inline-block">
                سجل كمعلم وأضف أول دورة
              </Link>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {featuredCourses.map(course => (
                <CourseCard key={course.id} course={course} />
              ))}
            </div>
          )}
        </div>
      </section>

      {/* Call to Action Section */}
      <section className="bg-primary-600 text-white py-16 px-4">
        <div className="container mx-auto text-center">
          <h2 className="text-3xl font-bold mb-4">هل أنت مستعد للبدء في رحلة التعلم؟</h2>
          <p className="text-xl mb-8 max-w-3xl mx-auto">
            انضم إلى آلاف الطلاب الذين يطورون مهاراتهم ويحققون أحلامهم من خلال منصتنا
          </p>
          <div className="flex flex-col sm:flex-row justify-center gap-4">
            <Link to="/register/student" className="bg-white text-primary-700 hover:bg-gray-100 px-8 py-3 rounded-md text-lg font-semibold transition-colors">
              سجل كطالب
            </Link>
            <Link to="/register/teacher" className="bg-transparent border-2 border-white hover:bg-white/10 px-8 py-3 rounded-md text-lg font-semibold transition-colors">
              سجل كمعلم
            </Link>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
